package store

import (
	"path/filepath"
	"testing"
)

// TestGetSyncState_NullColumnsDoNotError guards against a regression where a
// first-run or partial-sync row with a NULL last_cursor, last_synced_at, or
// total_count (the shape left behind by backfillColumns' ALTER TABLE ADD
// COLUMN, which has no DEFAULT for those two columns) made GetSyncState
// scan-fail. The failure was silent at the call sites: sync.go discarded the
// error and resumed with an empty cursor, forcing a full re-sync and
// repeating paid requests; data_source.go discarded the error and dropped
// the synced-at timestamp from local-read provenance. GetSyncState must
// surface whatever columns are actually populated instead of erroring out
// the whole row.
func TestGetSyncState_NullColumnsDoNotError(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	// Simulate a row left NULL by the ADD COLUMN backfill: only
	// resource_type is guaranteed to be non-NULL by any writer.
	if _, err := s.DB().Exec(
		`INSERT INTO sync_state (resource_type, last_cursor, last_synced_at, total_count) VALUES (?, NULL, NULL, NULL)`,
		"products",
	); err != nil {
		t.Fatalf("seed all-NULL sync_state row: %v", err)
	}

	cursor, lastSynced, count, err := s.GetSyncState("products")
	if err != nil {
		t.Fatalf("GetSyncState on all-NULL row returned error, want nil: %v", err)
	}
	if cursor != "" {
		t.Fatalf("cursor = %q, want empty string for NULL last_cursor", cursor)
	}
	if !lastSynced.IsZero() {
		t.Fatalf("lastSynced = %v, want zero time for NULL last_synced_at", lastSynced)
	}
	if count != 0 {
		t.Fatalf("count = %d, want 0 for NULL total_count", count)
	}

	// Partial-sync shape: a real cursor and timestamp landed, but total_count
	// stayed NULL (or vice versa) — none of the valid fields should be lost.
	if _, err := s.DB().Exec(
		`INSERT INTO sync_state (resource_type, last_cursor, last_synced_at, total_count) VALUES (?, ?, ?, NULL)`,
		"items", "page-2-cursor", "2026-01-01T00:00:00Z",
	); err != nil {
		t.Fatalf("seed partial sync_state row: %v", err)
	}

	cursor, lastSynced, count, err = s.GetSyncState("items")
	if err != nil {
		t.Fatalf("GetSyncState on partial row returned error, want nil: %v", err)
	}
	if cursor != "page-2-cursor" {
		t.Fatalf("cursor = %q, want %q preserved despite NULL total_count", cursor, "page-2-cursor")
	}
	if lastSynced.IsZero() {
		t.Fatalf("lastSynced is zero, want the seeded timestamp preserved despite NULL total_count")
	}
	if count != 0 {
		t.Fatalf("count = %d, want 0 for NULL total_count", count)
	}
}
